package com.yeyamo_mobile.api.partner_service.infrastructure.persistence;import com.yeyamo_mobile.api.partner_service.domain.model.*;import jakarta.persistence.*;@Entity@Table(name="artisan_kyc_requirements")public class ArtisanKycRequirementEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="country_code",nullable=false)private String countryCode;@Enumerated(EnumType.STRING)@Column(name="partner_type",nullable=false)private BusinessType partnerType;@Enumerated(EnumType.STRING)@Column(name="document_type",nullable=false)private DocumentType documentType;@Column(nullable=false)private boolean required;protected ArtisanKycRequirementEntity(){}public DocumentType getDocumentType(){return documentType;}public boolean isRequired(){return required;}}
